pub struct Entity55FindManyBuilder<'a, E> {
    executor: E,
    where_input: &'a crate::m_12_stress::Entity55WhereInput,
    order_by: Vec<crate::m_12_stress::Entity55OrderByWithRelationInput>,
    take: Option<i64>,
    skip: Option<i64>,
}

impl<'a, E> Entity55FindManyBuilder<'a, E> {
    pub fn order_by(
        mut self,
        order_by: &[crate::m_12_stress::Entity55OrderByWithRelationInput],
    ) -> Self {
        self.order_by = order_by.to_vec();
        self
    }

    pub fn take(mut self, n: i64) -> Self {
        self.take = Some(n);
        self
    }

    pub fn skip(mut self, n: i64) -> Self {
        self.skip = Some(n);
        self
    }

    pub async fn exec<'e>(self) -> sqlx::Result<Vec<crate::m_12_stress::Entity55>>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let mut qb = sqlx::QueryBuilder::new(
            r#"SELECT "id", "field_1", "field_2", "field_3", "field_4", "field_5", "field_6" FROM "table_entity55" WHERE "#,
        );
        if !crate::engine::sqlx_postgres::m_12_stress::push_entity55_where(
            &mut qb,
            self.where_input,
        ) {
            qb.push("TRUE");
        }
        if !self.order_by.is_empty() {
            qb.push(" ORDER BY ");
            let mut first = true;
            for ob in &self.order_by {
                if let Some(o) = ob.id {
                    if !first {
                        qb.push(", ");
                    }
                    first = false;
                    qb.push("\"id\" ");
                    qb.push(crate::engine::sqlx_postgres::filters::sort_order_sql(o));
                }
                if let Some(o) = ob.field_1 {
                    if !first {
                        qb.push(", ");
                    }
                    first = false;
                    qb.push("\"field_1\" ");
                    qb.push(crate::engine::sqlx_postgres::filters::sort_order_sql(o));
                }
                if let Some(o) = ob.field_2 {
                    if !first {
                        qb.push(", ");
                    }
                    first = false;
                    qb.push("\"field_2\" ");
                    qb.push(crate::engine::sqlx_postgres::filters::sort_order_sql(o));
                }
                if let Some(o) = ob.field_3 {
                    if !first {
                        qb.push(", ");
                    }
                    first = false;
                    qb.push("\"field_3\" ");
                    qb.push(crate::engine::sqlx_postgres::filters::sort_order_sql(o));
                }
                if let Some(o) = ob.field_4 {
                    if !first {
                        qb.push(", ");
                    }
                    first = false;
                    qb.push("\"field_4\" ");
                    qb.push(crate::engine::sqlx_postgres::filters::sort_order_sql(o));
                }
                if let Some(o) = ob.field_5 {
                    if !first {
                        qb.push(", ");
                    }
                    first = false;
                    qb.push("\"field_5\" ");
                    qb.push(crate::engine::sqlx_postgres::filters::sort_order_sql(o));
                }
                if let Some(o) = ob.field_6 {
                    if !first {
                        qb.push(", ");
                    }
                    first = false;
                    qb.push("\"field_6\" ");
                    qb.push(crate::engine::sqlx_postgres::filters::sort_order_sql(o));
                }
            }
        }
        if let Some(n) = self.take {
            qb.push(" LIMIT ");
            qb.push_bind(n);
        }
        if let Some(n) = self.skip {
            qb.push(" OFFSET ");
            qb.push_bind(n);
        }
        qb.build_query_as::<crate::m_12_stress::Entity55>()
            .fetch_all(self.executor)
            .await
    }
}

